"use client";

import { useCallback } from "react";
import Particles from "react-tsparticles";
import { loadFull } from "tsparticles";

const Particle = () => {
  const particlesInit = useCallback(async (engine: any) => {
    await loadFull(engine);
  }, []);

  const particlesLoaded = useCallback(async () => {}, []);
  return (
    <Particles
      className="h-screen"
      init={particlesInit}
      loaded={particlesLoaded}
      options={{
        fullScreen: { enable: false },
        fpsLimit: 120,
        interactivity: {
          events: {
            onHover: {
              enable: true,
              mode: "repulse",
            },
            resize: true,
          },
          modes: {
            repulse: {
              distance: 50,
              duration: 0.4,
            },
          },
        },

        particles: {
          color: {
            value: "#818286",
          },
          links: {
            color: "#818286",
            distance: 450,
            enable: true,
            opacity: 1,
            width: 2,
          },
          collisions: {
            enable: true,
          },
          move: {
            enable: false,
            direction: "bottom",
            outModes: {
              default: "bounce",
            },
            random: true,
            straight: false,
            speed: 1,
          },
          number: {
            density: {
              enable: true,
              area: 800,
            },
            value: 35,
          },
          opacity: {
            value: 1,
          },
          shape: {
            type: "circle",
          },
          size: {
            value: { min: 5, max: 20 },
          },
        },
        detectRetina: true,
      }}
    />
  );
};

export default Particle;

